"""Data model for tracking tax lots per security."""

from dataclasses import dataclass, field
from typing import List, Tuple


@dataclass
class Lot:
    """A single tax lot: a block of shares acquired at a specific price."""

    quantity: float
    cost_basis: float  # dollars paid per share for this block


@dataclass
class Position:
    """Tracks all open lots for one symbol, oldest lot first."""

    symbol: str
    lots: List[Lot] = field(default_factory=list)

    def add_lot(self, quantity: float, price: float) -> None:
        if quantity <= 0:
            raise ValueError("quantity must be positive")
        self.lots.append(Lot(quantity=quantity, cost_basis=price))

    def total_quantity(self) -> float:
        return sum(lot.quantity for lot in self.lots)

    def consume_fifo(self, quantity: float) -> List[Tuple[float, float]]:
        """Remove `quantity` shares oldest-first, returning (qty, price) pairs consumed."""
        held = self.total_quantity()
        if quantity > held:
            raise ValueError(
                f"cannot sell {quantity} shares of {self.symbol}; only {held} held"
            )

        consumed: List[Tuple[float, float]] = []
        remaining = quantity
        while remaining > 1e-9 and self.lots:
            lot = self.lots[0]
            if lot.quantity <= remaining + 1e-9:
                consumed.append((lot.quantity, lot.cost_basis))
                remaining -= lot.quantity
                self.lots.pop(0)
            else:
                consumed.append((remaining, lot.cost_basis))
                lot.quantity -= remaining
                remaining = 0.0
        return consumed

    def apply_return_of_capital(self, amount_per_share: float) -> None:
        """Adjust each open lot's basis for a non-dividend cash distribution."""
        for lot in self.lots:
            lot.cost_basis += amount_per_share

"""Entry point: replays a stream of transactions against a portfolio."""

from typing import Dict, List
from models import Position
from pricing import realized_pnl, unrealized_pnl, average_cost, apply_corporate_action


class PortfolioLedger:
    """Maintains positions across symbols and replays transactions against them."""

    def __init__(self) -> None:
        self.positions: Dict[str, Position] = {}
        self.realized_total: float = 0.0

    def _position_for(self, symbol: str) -> Position:
        if symbol not in self.positions:
            self.positions[symbol] = Position(symbol=symbol)
        return self.positions[symbol]

    def record_transactions(self, transactions: List[dict]) -> None:
        for txn in transactions:
            position = self._position_for(txn["symbol"])
            txn_type = txn["type"]
            if txn_type == "buy":
                position.add_lot(txn["quantity"], txn["price"])
            elif txn_type == "sell":
                self.realized_total += realized_pnl(position, txn["quantity"], txn["price"])
            elif txn_type == "corporate_action":
                apply_corporate_action(position, txn["action"], txn["amount_per_share"])
            else:
                raise ValueError(f"unknown transaction type: {txn_type}")

    def summary(self, current_prices: Dict[str, float]) -> dict:
        """Return realized P&L to date plus a snapshot of each open position."""
        positions_summary = []
        for symbol, position in self.positions.items():
            if position.total_quantity() == 0:
                continue
            positions_summary.append({
                "symbol": symbol,
                "quantity": position.total_quantity(),
                "average_cost": average_cost(position),
                "unrealized_pnl": unrealized_pnl(position, current_prices.get(symbol, 0.0)),
            })
        return {
            "realized_pnl": self.realized_total,
            "positions": positions_summary,
        }
